        changedFiles: doc.changedFiles,
        deliverables: doc.deliverables,
        guard: doc.guard,
        runs: doc.runs,
        verification: doc.verification,
        typecheck: doc.typecheck,
        verifier: doc.verifier,
        baseline: doc.baseline,
