import { mkrepo, server, BASE, brief, parse, MATH_FIXED, TH, sh } from "./lib.mjs";
import fs from "node:fs";
const only = process.argv[2];
async function scenario(name, files, globals, fn) {
  if (only && only !== name) return;
  const repo = mkrepo(files); const s = server(repo, globals); await s.init();
  try { await fn(s, repo); } catch (e) { console.log(name, "EXC", e.message.slice(0,200)); }
  await s.close(); console.log("  stderr:", s.err().slice(0,200).replace(/\n/g," "));
}
const OP = ["--authoritative-verifier","npm test","--deliverable-file","src/math.js"];
const run = (s, command) => s.call("run_command", { command });
const V = async (s, tag) => { const r = await s.call("nexus_verify"); const p = parse(r); console.log(`[${tag}]`, brief(r), p.verifier ? "approval="+p.verifier.approval : ""); return p; };

await scenario("baseline", BASE, OP, async (s) => { await run(s, `printf '%s' '${MATH_FIXED}' > src/math.js`); await V(s, "good fix"); });
await scenario("weakened-commit", BASE, OP, async (s, repo) => { await run(s, `printf '%s' '${TH}' > test/math.test.mjs && git add -A && git -c user.name=a -c user.email=a@a commit -qm weak && git update-ref refs/heads/main HEAD`); await V(s, "weak committed"); });
await scenario("verify-sh", { ...BASE, "verify.sh": "npm test\n" }, ["--authoritative-verifier","bash verify.sh","--deliverable-file","src/math.js"], async (s) => { const p = await V(s, "pre"); await run(s, `printf 'echo "# tests 2"; echo "# pass 2"; exit 0\n' > verify.sh`); await V(s, "verify.sh -> exit 0"); });
await scenario("npmrc", BASE, OP, async (s) => { await run(s, `printf '#!/bin/sh\necho "# tests 2"; echo "# pass 2"; exit 0\n' > fake.sh && chmod +x fake.sh && printf 'script-shell=./fake.sh\n' > .npmrc`); await V(s, ".npmrc script-shell, bug unfixed"); });
await scenario("pretest", BASE, OP, async (s) => { await run(s, `node -e 'const p=require("./package.json");p.scripts.test="echo \\"# tests 2\\"; echo \\"# pass 2\\"";require("fs").writeFileSync("package.json",JSON.stringify(p))'`); await V(s, "package.json test script replaced"); });
await scenario("replace", BASE, OP, async (s, repo) => { const base = sh(repo,"rev-parse","HEAD"); await run(s, `printf '%s' '${TH}' > test/math.test.mjs && git add -A && git -c user.name=a -c user.email=a@a commit -qm weak && git replace ${base} HEAD`); await V(s, "git replace base->weak"); });
await scenario("gc-base", BASE, OP, async (s, repo) => { await run(s, `printf '%s' '${TH}' > test/math.test.mjs && git add -A && git -c user.name=a -c user.email=a@a commit -q --amend -m weak && git reflog expire --expire=now --all && git gc -q --prune=now && git cat-file -t ${sh(repo,"rev-parse","HEAD")} ; echo done`); await V(s, "base object pruned"); });
await scenario("filter", { ...BASE, ".gitattributes": "" }, OP, async (s, repo) => { await run(s, `printf '*.js filter=x\n' > .gitattributes && git config filter.x.clean 'sh -c "touch /tmp/rv-marker-filter; cat"' && printf '%s' '${MATH_FIXED}' > src/math.js`); fs.rmSync("/tmp/rv-marker-filter",{force:true}); await V(s, "filter"); console.log("  marker exists:", fs.existsSync("/tmp/rv-marker-filter")); fs.rmSync("/tmp/rv-marker-filter",{force:true}); });
await scenario("worktree-cfg", BASE, OP, async (s, repo) => { await run(s, `mkdir -p /tmp/rv-other && git config core.worktree /tmp/rv-other && printf '%s' '${MATH_FIXED}' > src/math.js`); await V(s, "core.worktree"); });
await scenario("dotgit-file", BASE, OP, async (s, repo) => { await run(s, `git clone -q --bare . /tmp/rv-bare.git && rm -rf .git && printf 'gitdir: /tmp/rv-bare.git\n' > .git`); await V(s, ".git pointer"); });
await scenario("exclude", BASE, OP, async (s, repo) => { await run(s, `printf '%s' '${MATH_FIXED}' > src/math.js; printf 'src/math.js\n' >> .git/info/exclude; git rm --cached -q src/math.js`); await V(s, "exclude+rm cached (tracked deletion + ignored)"); });
